'use client';

import { FormEvent, useCallback, useEffect, useMemo, useState } from 'react';
import { ACTIVITY_TYPES, CREATABLE_ACTIVITY_TYPES, type ActivityDraft, type ActivityType } from '@/lib/activity-types';
import { ActivityPlayer } from '@/components/activity-player';
import { ManualActivityDialog } from '@/components/manual-activity-dialog';
import { AiStudioDialog, type AiStudioDefaults } from '@/components/ai-studio-dialog';
import { CourseFoldersView } from '@/components/course-folders-view';
import { DocumentLibraryView } from '@/components/document-library-view';
import { ApplicationsConnectionsView } from '@/components/applications-connections-view';
import { HelpCenter } from '@/components/help-center';
import { AdminSupportCenter } from '@/components/admin-support-center';
import { InstallApp, InstallAppButton } from '@/components/install-app';
import { BrandLockup, BrandMark } from '@/components/brand-logo';
import { LearnerPortal } from '@/components/learner-portal';
import { LearnerManagementView } from '@/components/learner-management-view';
import { detectPermissionLevel, PERMISSION_DEFINITIONS, PERMISSION_PRESETS, type PermissionLevel, type TrainerPermissions } from '@/lib/permissions';
import type { ResultCorrection } from '@/lib/result-corrections';
import { FEATURE_LABELS, SUBSCRIPTION_FEATURES, type PlanFeatures, type SubscriptionFeature } from '@/lib/subscriptions';

type User = { id: string; email: string; displayName: string | null; firstName: string | null; lastName: string | null; role: 'admin' | 'trainer' | 'learner'; status: string; permissions: TrainerPermissions };
type PlatformUser = { email: string; displayName: string };
type ActivityRecord = ActivityDraft & { id: string; status: 'draft' | 'published'; qualityScore: number; updatedAt: number };
type TrainerAccessRow = {
  id: string;
  status: string;
  requestedAt: number;
  trainerId: string;
  email: string;
  displayName: string | null;
  firstName: string | null;
  lastName: string | null;
  accountStatus: string;
  note: string | null;
  accessLevel: PermissionLevel;
  permissions: TrainerPermissions;
  planId: string | null;
  planName: string | null;
  subscriptionStatus: string | null;
  codeHint: string | null;
  codeExpiresAt: number | null;
  codeUsedAt: number | null;
};
type BillingMe = { plan:{id:string;name:string};status:string;renewsAt:number|null;resetAt:number;unlimited:boolean;voice:{monthUsedSeconds:number;monthLimitSeconds:number;dayUsedSeconds:number;dayLimitSeconds:number;percent:number;remainingSeconds:number|null};credits:{available:number|null};features:PlanFeatures;alert:{level:string;message:string} };
type BillingPlan = { id:string;name:string;priceCents:number;currency:string;monthlyVoiceSeconds:number;dailyVoiceSeconds:number;monthlyCredits:number;monthlyApiBudgetMicros:number;features:PlanFeatures;creditCosts:Record<string,number>;active:boolean;updatedAt:number };
type BillingMember = { id:string;email:string;displayName:string|null;firstName:string|null;lastName:string|null;role:'admin'|'trainer';status:string;createdAt:number;entitlement:{planId:string;planName:string;subscriptionStatus:string;startsAt:number;renewsAt:number|null;endsAt:number|null;resetAt:number;updatedAt:number;unlimited:boolean;creditsRemaining:number;voiceSecondsMonth:number;voiceSecondsDay:number;monthlyVoiceLimit:number;dailyVoiceLimit:number;apiCostMicrosMonth:number;apiBudgetMicros:number;voicePercent:number;apiPercent:number;features:PlanFeatures;overrides:Array<{feature:string;allowed:boolean;expiresAt:number|null}>};history:Array<{id:string;action:string;fromPlanId:string|null;toPlanId:string|null;createdAt:number}>;usage:Array<{id:string;feature:string;audioSeconds:number;creditsCharged:number;createdAt:number}> };
type AdminBillingData = { plans:BillingPlan[];members:BillingMember[];totals:{users:number;active:number;suspended:number;voiceSeconds:number;apiCostMicros:number;creditsUsed:number;nearLimit:number;byPlan:Record<string,number>};aiSecurity:{requestsPerMinute:number;requestsPerDay:number;globalRequestsPerDay:number;globalDailyBudgetMicros:number;maxJsonBytes:number} };
type ApiResult<T> = { ok: true; data: T } | { ok: false; error: { message: string; code: string } };
type Section = 'dashboard' | 'activities' | 'voice-coach' | 'documents' | 'results' | 'learners' | 'connections' | 'admin';

const tones = ['mint','blue','peach','aqua'];
const symbols = ['?','♫','↕','✓','▦','◌','ABC','▧','◫','⌨','≡','▤','⇄','◎','★','▣','⌘','◧','↔','A','●','◉','➜','▥','◔','✺','?','▦','⌁','◉'];

async function api<T>(url: string, options?: RequestInit): Promise<T> {
  const response = await fetch(url, options);
  const payload = await response.json() as ApiResult<T>;
  if (!payload.ok) throw new Error(payload.error.message);
  return payload.data;
}

export function ProgressedApp({ initialAuthOpen = false,initialResetToken = '',initialAccess = null,initialPlatformUser = null,initialAdminInitialized = false,initialSection='dashboard' }: { initialAuthOpen?: boolean; initialResetToken?: string; initialAccess?:'learner'|null; initialPlatformUser?: PlatformUser | null; initialAdminInitialized?: boolean; initialSection?:Section }) {
  const [section,setSection] = useState<Section>(initialSection); const [user,setUser] = useState<User | null>(null); const [activities,setActivities] = useState<ActivityRecord[]>([]);
  const [authOpen,setAuthOpen] = useState(initialAuthOpen); const [authMode,setAuthMode] = useState<'login'|'register'>('login'); const [studioOpen,setStudioOpen] = useState(false); const [manualType,setManualType] = useState<ActivityType | null>(null); const [editingActivity,setEditingActivity] = useState<ActivityRecord | null>(null); const [renamingActivity,setRenamingActivity] = useState<ActivityRecord | null>(null); const [playing,setPlaying] = useState<ActivityRecord | null>(null);
  const [studioDefaults,setStudioDefaults] = useState<AiStudioDefaults|null>(null);
  const [toast,setToast] = useState(''); const [loading,setLoading] = useState(true); const [query,setQuery] = useState(''); const [resultStats,setResultStats] = useState({ count:0, average:null as number | null });
  const notify = useCallback((message: string) => { setToast(message); window.setTimeout(() => setToast(''), 3200); }, []);
  const loadActivities = useCallback(async () => { try { const [activityData,resultData] = await Promise.all([api<{ activities: ActivityRecord[] }>('/api/activities'),api<{ results: Array<{ percentage:number }> }>('/api/results')]); setActivities(activityData.activities); setResultStats({ count:resultData.results.length, average:resultData.results.length ? Math.round(resultData.results.reduce((sum,row) => sum + Number(row.percentage),0) / resultData.results.length) : null }); } catch (error) { notify(error instanceof Error ? error.message : 'Chargement impossible.'); } }, [notify]);
  useEffect(() => { api<{ user: User | null }>('/api/auth/me').then((data) => { setUser(data.user); if (data.user) { setAuthOpen(false); if(data.user.role !== 'learner') void loadActivities(); } }).catch(() => setUser(null)).finally(() => setLoading(false)); }, [loadActivities]);
  const filtered = useMemo(() => activities.filter((activity) => `${activity.title} ${activity.theme}`.toLowerCase().includes(query.toLowerCase())), [activities,query]);
  const resultsCount = resultStats.count;
  const openAuth = (mode: 'login'|'register' = 'login') => { setAuthMode(mode); setAuthOpen(true); };
  const openStudio = (defaults?:AiStudioDefaults) => { setStudioDefaults(defaults??null); setStudioOpen(true); };
  const selectSection = (next: Section) => { if (!user && next !== 'dashboard') { openAuth('login'); notify('Connectez-vous pour accéder à votre espace sécurisé.'); return; } setSection(next); };
  const removeActivity = async (activity: ActivityRecord) => { if (!window.confirm('Voulez-vous vraiment supprimer cette activité ?')) return; try { await api(`/api/activities/${activity.id}?deleteFiles=true`, { method: 'DELETE' }); setActivities((items) => items.filter((item) => item.id !== activity.id)); notify('L’activité a été supprimée.'); } catch (error) { notify(error instanceof Error ? error.message : 'Suppression impossible.'); } };
  const duplicateActivity = async (activity: ActivityRecord) => { try { await api(`/api/activities/${activity.id}`, { method: 'POST' }); await loadActivities(); notify('Une copie a été ajoutée à votre bibliothèque.'); } catch (error) { notify(error instanceof Error ? error.message : 'Duplication impossible.'); } };
  const togglePublish = async (activity: ActivityRecord) => { try { await api(`/api/activities/${activity.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ ...activity, status: activity.status === 'published' ? 'draft' : 'published' }) }); await loadActivities(); notify(activity.status === 'published' ? 'Activité remise en brouillon.' : 'Activité publiée.'); } catch (error) { notify(error instanceof Error ? error.message : 'Modification impossible.'); } };
  const renameActivity = async (title:string) => { if(!renamingActivity)return; try { await api(`/api/activities/${renamingActivity.id}`, { method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({title}) }); await loadActivities(); setRenamingActivity(null); notify(`Le cours ou jeu pédagogique s’appelle maintenant « ${title.trim()} ».`); } catch(error) { notify(error instanceof Error ? error.message : 'Renommage impossible.'); } };

  if(user?.role==='learner')return <LearnerPortal onLogout={async()=>{await api('/api/auth/logout',{method:'POST'});setUser(null);setSection('dashboard');setAuthOpen(true);notify('Vous êtes déconnecté.');}}/>;
  return <main className="app-frame">
    <Sidebar user={user} section={section} counts={{ activities: activities.length, results: resultsCount }} onSelect={selectSection} onCreate={() => user ? openStudio() : openAuth('login')} onLogout={async () => { await api('/api/auth/logout',{ method:'POST' }); setUser(null); setActivities([]); setResultStats({count:0,average:null}); setSection('dashboard'); notify('Vous êtes déconnecté.'); }} />
    <section className="workspace" id="top">
      <AppHeader user={user} query={query} onQuery={setQuery} onAuth={() => openAuth('login')} onCreate={() => user ? openStudio() : openAuth('login')} />
      {!user && !loading && <div className="access-banner"><span>🔒</span><div><strong>Première utilisation ? Créez simplement votre compte</strong><p>L’adresse responsable reconnue devient administrateur ; les autres inscriptions attendent votre validation.</p></div><div className="access-banner-actions"><button className="button light" type="button" onClick={() => openAuth('login')}>Me connecter</button><button className="button dark" type="button" onClick={() => openAuth('register')}>Créer mon compte</button></div></div>}
      {section === 'dashboard' && <Dashboard activities={filtered} folderActivities={activities} user={user} resultStats={resultStats} onStudio={(defaults) => user ? openStudio(defaults) : openAuth('login')} onManual={(type) => user ? setManualType(type) : openAuth('login')} onPlay={setPlaying} onOpenLibrary={() => selectSection('activities')} notify={notify} />}
      {section === 'activities' && <ActivitiesView activities={activities} query={query} onQuery={setQuery} onPlay={setPlaying} onEdit={setEditingActivity} onRename={setRenamingActivity} onDelete={removeActivity} onDuplicate={duplicateActivity} onPublish={togglePublish} onCreate={openStudio} notify={notify} />}
      {section === 'voice-coach' && <VoiceCoachLibraryView activities={activities.filter((activity)=>activity.type==='voice-coach')} onCreate={()=>setManualType('voice-coach')} onPlay={setPlaying} onEdit={setEditingActivity} onRename={setRenamingActivity} onDelete={removeActivity} onPublish={togglePublish}/>}
      {section === 'documents' && user && <DocumentLibraryView notify={notify} />}
      {section === 'results' && user && <ResultsView activities={activities} notify={notify} />}
      {section === 'learners' && user && <LearnerManagementView isAdmin={user.role==='admin'} notify={notify}/>}
      {section === 'connections' && user && <ApplicationsConnectionsView notify={notify} />}
      {section === 'admin' && user?.role === 'admin' && <AdminView notify={notify} />}
      {section === 'admin' && user?.role !== 'admin' && <EmptyState title="Administration non disponible" copy="Cette rubrique est réservée au compte administrateur." />}
    </section>
    {authOpen && <AuthDialog resetToken={initialResetToken} initialMode={authMode} initialAccess={initialAccess} platformUser={initialPlatformUser} adminInitialized={initialAdminInitialized} onClose={() => setAuthOpen(false)} onAuthenticated={(next) => { setUser(next); setAuthOpen(false); if (next.role === 'admin') setSection('admin'); else if(next.role==='learner')setSection('dashboard'); if(next.role!=='learner')void loadActivities(); notify(next.role === 'admin' ? 'Compte administrateur connecté. Vous pouvez piloter les accès.' : next.role==='learner'?'Bienvenue dans votre espace apprenant.':'Connexion réussie.'); }} />}
    {studioOpen && <AiStudioDialog defaults={studioDefaults} onClose={() => {setStudioOpen(false);setStudioDefaults(null);}} onCreated={async (message) => { setStudioOpen(false);setStudioDefaults(null);await loadActivities();setSection('activities');notify(message); }} />}
    {manualType && <ManualActivityDialog type={manualType} onClose={() => setManualType(null)} onCreated={async () => { setManualType(null); await loadActivities(); setSection('activities'); notify('L’activité et son support pédagogique sont enregistrés.'); }} />}
    {editingActivity && <ManualActivityDialog type={editingActivity.type} initial={editingActivity} onClose={() => setEditingActivity(null)} onCreated={async () => { setEditingActivity(null); await loadActivities(); setSection('activities'); notify('Les modifications de l’activité sont enregistrées.'); }} />}
    {renamingActivity && <RenameActivityDialog activity={renamingActivity} onClose={()=>setRenamingActivity(null)} onSave={renameActivity}/>}
    {playing && <ActivityPlayer activity={playing} canManageImages onClose={() => setPlaying(null)} />}
    <HelpCenter user={user} />
    <InstallApp />
    {toast && <div className="toast" role="status" aria-live="polite">{toast}</div>}
  </main>;
}

function Sidebar({ user,section,counts,onSelect,onCreate,onLogout }: { user: User | null; section: Section; counts: { activities: number; results: number }; onSelect: (section: Section) => void; onCreate: () => void; onLogout: () => void }) {
  const items: Array<{ id: Section; label: string; icon: string; badge?: number }> = [{ id:'dashboard',label:'Tableau de bord',icon:'⌂'},{id:'activities',label:'Activités',icon:'◇',badge:counts.activities},{id:'voice-coach',label:'Coach vocal – Langues',icon:'◉'},{id:'documents',label:'Ma base documentaire',icon:'▤'},{id:'results',label:'Résultats',icon:'▥',badge:counts.results},{id:'learners',label:user?.role==='admin'?'Gestion des apprenants':'Mes apprenants',icon:'♙'},{id:'connections',label:'Applications et connexions',icon:'↗'},{id:'admin',label:'Administration',icon:'⬡'}];
  return <aside className="sidebar"><button className="brand brand-button" type="button" onClick={() => onSelect('dashboard')} aria-label="Progressed Pédago, accueil"><BrandLockup priority/></button><nav aria-label="Navigation principale">{items.map((item) => <button className={`nav-item ${section === item.id ? 'active' : ''}`} type="button" aria-current={section===item.id?'page':undefined} onClick={() => onSelect(item.id)} key={item.id}><span className="nav-icon" aria-hidden="true">{item.icon}</span><span>{item.label}</span>{typeof item.badge === 'number' && <span className="nav-badge">{item.badge}</span>}</button>)}<InstallAppButton /></nav><section className="ai-card"><span className="sparkle">✦</span><h2>Assistant pédagogique IA</h2><p>Partez d’une idée, d’un PDF, d’une vidéo ou d’un lien pour créer le cours, l’activité et le PowerPoint.</p><button className="button lime full" type="button" onClick={onCreate}>Créer avec l’IA</button></section><div className="profile"><span className="avatar">{user ? initials(user.displayName ?? user.email) : 'PP'}</span><span><strong>{user?.displayName ?? 'Espace sécurisé'}</strong><small>{user ? (user.role === 'admin' ? 'Administrateur' : 'Formateur') : 'Non connecté'}</small></span>{user && <button type="button" onClick={onLogout} aria-label="Se déconnecter">↪</button>}</div></aside>;
}

function AppHeader({ user,query,onQuery,onAuth,onCreate }: { user: User | null; query: string; onQuery: (value: string) => void; onAuth: () => void; onCreate: () => void }) {
  return <header className="workspace-header"><div><p className="overline">Espace formateur</p><h1>{user ? `Bonjour ${firstName(user.displayName ?? user.email)}, prêt à transmettre ?` : 'Le studio pédagogique de Progressed Solution.'}</h1></div><div className="header-actions"><label className="search"><span className="sr-only">Rechercher une activité</span><span>⌕</span><input type="search" value={query} onChange={(event) => onQuery(event.target.value)} placeholder="Rechercher…" /></label>{user ? <button className="button dark" type="button" onClick={onCreate}>＋ Créer une activité</button> : <button className="button dark" type="button" onClick={onAuth}>Se connecter</button>}</div></header>;
}

function Dashboard({ activities,folderActivities,user,resultStats,onStudio,onManual,onPlay,onOpenLibrary,notify }: { activities: ActivityRecord[]; folderActivities: ActivityRecord[]; user: User | null; resultStats: { count:number; average:number | null }; onStudio: (defaults?:AiStudioDefaults) => void; onManual: (type: ActivityType) => void; onPlay: (activity: ActivityRecord) => void; onOpenLibrary: () => void; notify: (message:string) => void }) {
  return <><section className="hero"><div className="hero-copy"><span className="pill">✧ Création assistée par IA</span><h2>Un prompt, une vidéo ou un PDF devient un cours vivant.</h2><p>Créez un cours détaillé, une activité interactive et un véritable PowerPoint depuis vos consignes, YouTube, un document ou une page web.</p><div className="hero-actions"><button className="button dark" type="button" onClick={()=>onStudio()}>Ouvrir le studio IA →</button><button className="button light" type="button" onClick={() => onManual('quiz')}>Créer manuellement</button></div></div><div className="document-card"><span>Votre source</span><strong>Prompt · PDF · YouTube · Web</strong><div className="document-line" /><div className="document-status"><i>● ● ●</i><b>Cours + activité + PPT prêts ✓</b></div></div></section><section className="metrics" aria-label="Indicateurs"><article><span className="metric-icon mint">◇</span><strong>{folderActivities.length}</strong><small>activités disponibles</small></article><article><span className="metric-icon lilac">♙</span><strong>{resultStats.count}</strong><small>participations reçues</small></article><article><span className="metric-icon yellow">▥</span><strong>{resultStats.average === null ? '—' : `${resultStats.average}%`}</strong><small>réussite moyenne</small></article><article><span className="metric-icon blush">↗</span><strong>6</strong><small>applications intégrables</small></article></section>{user&&<UsageCard/>}{user && <CourseFoldersView activities={folderActivities} onPlay={onPlay} notify={notify} onCreateWithAi={onStudio} />}<section className="section-block dashboard-library-section"><div className="section-heading"><div><p className="overline">Votre bibliothèque</p><h2>Un aperçu de vos dernières activités.</h2></div>{user && <button className="button light dashboard-library-all" type="button" onClick={onOpenLibrary}>Voir toutes les activités <span>{folderActivities.length}</span> →</button>}</div>{user && activities.length ? <DashboardLibraryPreview activities={activities.slice(0,3)} onPlay={onPlay} /> : <EmptyState title={user ? 'Votre bibliothèque est prête' : 'Vos activités apparaîtront ici'} copy={user ? 'Créez votre première activité manuellement ou avec votre IA personnelle.' : 'Connectez-vous pour retrouver uniquement les contenus qui vous appartiennent.'} action={user ? ()=>onStudio() : onOpenLibrary} />}</section><section className="section-block"><div className="section-heading"><div><p className="overline">Choisir un format</p><h2>Cinq activités essentielles.</h2></div><span>{CREATABLE_ACTIVITY_TYPES.length} formats disponibles</span></div><div className="format-grid">{CREATABLE_ACTIVITY_TYPES.map(([type,title,copy],index) => <button className={`format-card ${tones[index % tones.length]}`} type="button" onClick={() => onManual(type)} key={type}><span className="format-icon">{symbols[ACTIVITY_TYPES.findIndex(([candidate])=>candidate===type)]??'?'}</span><h3>{title}</h3><p>{copy}</p><b>Créer →</b></button>)}</div></section></>;
}

function UsageCard(){const[data,setData]=useState<BillingMe|null>(null);const load=useCallback(()=>api<BillingMe>('/api/billing/me').then(setData).catch(()=>setData(null)),[]);useEffect(()=>{void load();const refresh=()=>void load();const timer=window.setInterval(refresh,30_000);window.addEventListener('voice-usage-updated',refresh);return()=>{window.clearInterval(timer);window.removeEventListener('voice-usage-updated',refresh);};},[load]);if(!data)return null;const visiblePercent=data.voice.monthUsedSeconds>0?Math.max(1,data.voice.percent):0;return <section className={`usage-card ${data.alert.level}`}><header><div><p className="overline">Ma consommation IA</p><h2>Votre formule : {data.plan.name}</h2></div><span className="usage-plan">{data.status==='trial'?'Essai':data.unlimited?'Accès administrateur':'Abonnement actif'}</span></header><div className="usage-grid"><article><span>Vocal IA ce mois</span><strong>{formatVoiceDuration(data.voice.monthUsedSeconds)} {data.unlimited?'utilisées':`/ ${formatVoiceDuration(data.voice.monthLimitSeconds)}`}</strong><div className="usage-progress" aria-label={`${data.voice.percent} % utilisé`}><i style={{width:`${visiblePercent}%`}}/></div><small>{data.unlimited?'Quota illimité':`${data.voice.percent} % utilisé · ${formatVoiceDuration(data.voice.remainingSeconds??0)} restantes`}</small></article><article><span>Aujourd’hui</span><strong>{formatVoiceDuration(data.voice.dayUsedSeconds)} {data.unlimited?'utilisées':`/ ${formatVoiceDuration(data.voice.dayLimitSeconds)}`}</strong><small>Actualisation automatique après chaque séance.</small></article><article><span>Crédits disponibles</span><strong>{data.credits.available===null?'Illimités':data.credits.available}</strong><small>Les cours déjà créés restent disponibles sans nouveau coût.</small></article><article><span>Renouvellement</span><strong>{new Date((data.renewsAt??data.resetAt)*1000).toLocaleDateString('fr-FR')}</strong><small>Les compteurs mensuels seront remis à zéro automatiquement.</small></article></div><p className="usage-alert">{data.alert.message}{data.alert.level==='blocked'?' Vous pouvez continuer votre apprentissage en mode texte.':''}</p></section>}

function DashboardLibraryPreview({ activities,onPlay }: { activities: ActivityRecord[]; onPlay: (activity: ActivityRecord) => void }) { return <div className="dashboard-library-preview">{activities.map((activity,index) => <button className="dashboard-library-card" type="button" onClick={() => onPlay(activity)} key={activity.id}><span className={`dashboard-library-icon ${tones[index % tones.length]}`} aria-hidden="true">{symbols[ACTIVITY_TYPES.findIndex(([type]) => type === activity.type)] ?? '?'}</span><span className="dashboard-library-copy"><small>{ACTIVITY_TYPES.find(([type]) => type === activity.type)?.[1] ?? activity.type} · {activity.theme}</small><strong>{activity.title}</strong><span>{activity.durationMinutes} min · {activity.status === 'published' ? 'Publié' : 'Brouillon'}</span></span><b aria-hidden="true">Ouvrir →</b></button>)}</div>; }

function Library({ activities,onPlay,onEdit,onRename,onDelete,onDuplicate,onPublish }: { activities: ActivityRecord[]; onPlay: (activity: ActivityRecord) => void; onEdit?: (activity: ActivityRecord) => void; onRename?: (activity: ActivityRecord) => void; onDelete: (activity: ActivityRecord) => void; onDuplicate?: (activity: ActivityRecord) => void; onPublish?: (activity: ActivityRecord) => void }) { return <div className="library-grid">{activities.map((activity,index) => <article className="activity-card" key={activity.id}><div className={`activity-cover ${tones[index % tones.length]}`}><span className="cover-tag">{ACTIVITY_TYPES.find(([type]) => type === activity.type)?.[1] ?? activity.type}</span><strong>{symbols[ACTIVITY_TYPES.findIndex(([type]) => type === activity.type)] ?? '?'}</strong><button type="button" onClick={() => onPlay(activity)} aria-label={`Lancer ${activity.title}`}>⛶</button></div><div className="activity-body"><small>{activity.theme}</small><h3>{activity.title}</h3><div><span>{activity.durationMinutes} min · qualité {activity.qualityScore}%</span><span className={`status-pill ${activity.status}`}>{activity.status === 'published' ? 'Publié' : 'Brouillon'}</span></div><div className="card-actions"><button type="button" onClick={() => onPlay(activity)}>Lancer</button>{onRename && <button type="button" onClick={() => onRename(activity)}>✎ Renommer</button>}{onEdit && <button type="button" onClick={() => onEdit(activity)}>Modifier le contenu</button>}{onDuplicate && <button type="button" onClick={() => onDuplicate(activity)}>Dupliquer</button>}{onPublish && <button type="button" onClick={() => onPublish(activity)}>{activity.status === 'published' ? 'Dépublier' : 'Publier'}</button>}<button className="danger" type="button" onClick={() => onDelete(activity)}>Supprimer</button></div></div></article>)}</div>; }

function ActivitiesView({ activities,query,onQuery,onPlay,onEdit,onRename,onDelete,onDuplicate,onPublish,onCreate,notify }: { activities: ActivityRecord[]; query: string; onQuery: (value: string) => void; onPlay: (activity: ActivityRecord) => void; onEdit: (activity: ActivityRecord) => void; onRename: (activity: ActivityRecord) => void; onDelete: (activity: ActivityRecord) => void; onDuplicate: (activity: ActivityRecord) => void; onPublish: (activity: ActivityRecord) => void; onCreate: (defaults?:AiStudioDefaults) => void; notify:(message:string)=>void }) { const [status,setStatus] = useState(''); const visible = activities.filter((activity) => (!status || activity.status === status) && `${activity.title} ${activity.theme}`.toLowerCase().includes(query.toLowerCase())); return <section className="page-view"><div className="page-title"><div><p className="overline">Bibliothèque privée</p><h2>Vos cours et activités pédagogiques.</h2></div><button className="button dark" type="button" onClick={()=>onCreate()}>＋ Nouvelle activité</button></div><CourseFoldersView activities={activities} onPlay={onPlay} notify={notify} onCreateWithAi={onCreate} /><div className="all-activities-heading"><div><p className="overline">Bibliothèque complète</p><h3>Toutes les activités</h3></div></div><div className="filters"><input type="search" value={query} onChange={(event) => onQuery(event.target.value)} placeholder="Rechercher par titre ou thème" /><select aria-label="Filtrer par statut" value={status} onChange={(event) => setStatus(event.target.value)}><option value="">Tous les statuts</option><option value="draft">Brouillons</option><option value="published">Publiés</option></select></div>{visible.length ? <Library activities={visible} onPlay={onPlay} onEdit={onEdit} onRename={onRename} onDelete={onDelete} onDuplicate={onDuplicate} onPublish={onPublish} /> : <EmptyState title="Aucune activité trouvée" copy="Modifiez les filtres ou créez votre première activité." action={()=>onCreate()} />}</section>; }

function VoiceCoachLibraryView({activities,onCreate,onPlay,onEdit,onRename,onDelete,onPublish}:{activities:ActivityRecord[];onCreate:()=>void;onPlay:(activity:ActivityRecord)=>void;onEdit:(activity:ActivityRecord)=>void;onRename:(activity:ActivityRecord)=>void;onDelete:(activity:ActivityRecord)=>void;onPublish:(activity:ActivityRecord)=>void}) { return <section className="page-view voice-coach-library"><div className="page-title"><div><p className="overline">Nouvelle section indépendante</p><h2>Coach vocal – Apprentissage des langues.</h2><p>Préparez une conversation progressive, partagez-la dans un parcours et retrouvez le bilan de chaque apprenant.</p></div><button className="button dark" type="button" onClick={onCreate}>＋ Créer une séance vocale</button></div><section className="voice-coach-feature-grid"><article><span>1</span><strong>Configurer</strong><p>Langue, niveau CECRL, thème, vocabulaire, débit et niveau de correction.</p></article><article><span>2</span><strong>Faire parler</strong><p>Une consigne à la fois, écoute réelle, répétition et aide traduite si nécessaire.</p></article><article><span>3</span><strong>Suivre</strong><p>Durée, échanges, réussites, corrections et conseil pour la prochaine séance.</p></article></section>{activities.length?<Library activities={activities} onPlay={onPlay} onEdit={onEdit} onRename={onRename} onDelete={onDelete} onPublish={onPublish}/>:<EmptyState title="Aucune séance vocale" copy="Créez une première séance puis ajoutez-la à un parcours comme n’importe quelle autre activité." action={onCreate}/>}</section>; }

function RenameActivityDialog({activity,onClose,onSave}:{activity:ActivityRecord;onClose:()=>void;onSave:(title:string)=>Promise<void>}) { const [busy,setBusy]=useState(false); const submit=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const form=new FormData(event.currentTarget);setBusy(true);try{await onSave(String(form.get('title')??''));}finally{setBusy(false);}};return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="rename-activity-title"><form className="modal-card rename-main-folder-dialog" onSubmit={(event)=>void submit(event)}><button className="modal-close" type="button" onClick={onClose} aria-label="Fermer">×</button><p className="overline">Cours ou jeu pédagogique</p><h2 id="rename-activity-title">Renommer le contenu</h2><p>Seul le titre sera modifié. Les questions, exercices, images, résultats et dossiers associés seront conservés.</p><label>Nouveau titre<input name="title" required minLength={3} maxLength={300} autoFocus defaultValue={activity.title}/></label><div className="modal-actions"><button className="button light" type="button" onClick={onClose}>Annuler</button><button className="button dark" disabled={busy}>{busy?'Renommage…':'Enregistrer le nouveau titre'}</button></div></form></div>; }

function ResultsView({ activities,notify }: { activities: ActivityRecord[]; notify: (message: string) => void }) {
  const [rows,setRows] = useState<Array<Record<string,unknown>>>([]);
  const [selected,setSelected] = useState<Record<string,unknown>|null>(null);
  const [themes,setThemes] = useState<Array<{id:string;name:string}>>([]);
  const [trainings,setTrainings] = useState<Array<{id:string;mainFolderId:string|null;name:string}>>([]);
  const [sessions,setSessions] = useState<Array<{id:string;trainingId:string;shortCode:string;mode:string;status:string}>>([]);
  const [search,setSearch] = useState(''); const [activityId,setActivityId] = useState(''); const [trainingId,setTrainingId] = useState(''); const [mainFolderId,setMainFolderId] = useState(''); const [shareId,setShareId]=useState('');
  useEffect(() => { api<{mainFolders:Array<{id:string;name:string}>;folders:Array<{id:string;mainFolderId:string|null;name:string}>}>('/api/folders').then((data) => { setThemes(data.mainFolders); setTrainings(data.folders); }).catch((error) => notify(error.message)); },[notify]);
  useEffect(() => { const params=new URLSearchParams({search}); if(activityId)params.set('activityId',activityId);if(trainingId)params.set('trainingId',trainingId);if(mainFolderId)params.set('mainFolderId',mainFolderId);if(shareId)params.set('shareId',shareId);api<{results:Array<Record<string,unknown>>;sessions:Array<{id:string;trainingId:string;shortCode:string;mode:string;status:string}>}>(`/api/results?${params}`).then((data)=>{setRows(data.results);setSessions(data.sessions);}).catch((error)=>notify(error.message)); },[search,activityId,trainingId,mainFolderId,shareId,notify]);
  const exportParams=new URLSearchParams(); if(activityId)exportParams.set('activityId',activityId);if(trainingId)exportParams.set('trainingId',trainingId);if(mainFolderId)exportParams.set('mainFolderId',mainFolderId);if(shareId)exportParams.set('shareId',shareId);
  const availableTrainings=mainFolderId?trainings.filter((training)=>training.mainFolderId===mainFolderId):trainings;
  const availableSessions=trainingId?sessions.filter((session)=>session.trainingId===trainingId):sessions;
  return <section className="page-view"><div className="page-title"><div><p className="overline">Suivi des apprenants</p><h2>Résultats, points et corrections détaillées.</h2></div><div className="page-title-actions"><a className="button light" href={`/api/results/export?${exportParams}&format=pdf`}>Exporter en PDF</a><a className="button dark" href={`/api/results/export?${exportParams}&format=excel`}>Exporter pour Excel</a></div></div><div className="results-summary-note"><span>✓</span><p><strong>Un espace complet pour chaque exercice</strong>Ouvrez une participation pour revoir le score, les réponses données, les solutions attendues et les explications pédagogiques.</p></div><div className="filters results-filters"><input type="search" value={search} onChange={(event)=>setSearch(event.target.value)} placeholder="Rechercher un apprenant"/><select aria-label="Filtrer par grand thème" value={mainFolderId} onChange={(event)=>{setMainFolderId(event.target.value);setTrainingId('');setShareId('');}}><option value="">Tous les grands thèmes</option>{themes.map((theme)=><option value={theme.id} key={theme.id}>{theme.name}</option>)}</select><select aria-label="Filtrer par formation" value={trainingId} onChange={(event)=>{setTrainingId(event.target.value);setShareId('');}}><option value="">Toutes les formations</option>{availableTrainings.map((training)=><option value={training.id} key={training.id}>{training.name}</option>)}</select><select aria-label="Filtrer par session" value={shareId} onChange={(event)=>setShareId(event.target.value)}><option value="">Toutes les sessions</option>{availableSessions.map((session)=><option value={session.id} key={session.id}>{session.shortCode} · {session.mode==='classroom'?'Salle':'Domicile'} · {session.status==='active'?'Active':'Fermée'}</option>)}</select><select aria-label="Filtrer par activité" value={activityId} onChange={(event)=>setActivityId(event.target.value)}><option value="">Toutes les activités</option>{activities.map((activity)=><option value={activity.id} key={activity.id}>{activity.title}</option>)}</select></div>{rows.length?<div className="results-table results-hierarchy-table"><div className="table-row table-head"><span>Apprenant</span><span>Grand thème / formation</span><span>Activité / session</span><span>Score</span><span>Date</span></div>{rows.map((row)=><div className="table-row" key={String(row.id)}><span><strong>{String(row.learnerFirstName)} {String(row.learnerLastName)}</strong></span><span><strong>{row.trainingTitle?String(row.trainingTitle):'Hors parcours'}</strong><small>{row.mainFolderTitle?String(row.mainFolderTitle):'Activité autonome'}</small></span><span><strong>{String(row.activityTitle)}</strong><small>{row.sessionShortCode?`Session ${String(row.sessionShortCode)} · ${row.sessionMode==='classroom'?'Salle':'Domicile'}`:'Participation directe'}</small><button className="result-detail-button" type="button" onClick={()=>setSelected(row)}>Voir le score et le corrigé →</button></span><span><strong>{String(row.score)} / {String(row.maxScore)}</strong><small>{String(row.percentage)}% · {String(row.attempt)} tentative{Number(row.attempt)>1?'s':''}</small></span><span>{new Date(Number(row.createdAt)*1000).toLocaleDateString('fr-FR')}</span></div>)}</div>:<EmptyState title="Aucun résultat pour le moment" copy="Les participations apparaîtront ici dès qu’une activité publiée sera terminée."/>}{selected&&<ResultDetailDialog row={selected} onClose={()=>setSelected(null)}/>}</section>;
}

function ResultDetailDialog({row,onClose}:{row:Record<string,unknown>;onClose:()=>void}) { const correction=row.correctionDetails as ResultCorrection|undefined;const report=correction?.report??null;const stringList=(value:unknown)=>Array.isArray(value)?value.map(String):[];return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="result-detail-title"><section className="modal-card result-detail-dialog"><button className="modal-close" type="button" onClick={onClose} aria-label="Fermer">×</button><p className="overline">Résultat apprenant</p><h2 id="result-detail-title">{String(row.activityTitle)}</h2><p>{String(row.learnerFirstName)} {String(row.learnerLastName)} · {new Date(Number(row.createdAt)*1000).toLocaleString('fr-FR')}</p><div className="result-detail-score"><strong>{String(row.score)}<small> / {String(row.maxScore)} points</small></strong><span>{String(row.percentage)}%</span><p>{Number(row.durationSeconds)?`Durée : ${Math.max(1,Math.round(Number(row.durationSeconds)/60))} min`:'Durée non renseignée'}</p></div>{correction&&<><div className="result-correction-summary"><strong>Correction générale</strong><p>{correction.summary}</p></div>{correction.items.length>0&&<div className="exercise-correction-list">{correction.items.map((item,index)=><article className={item.correct?'correct':'wrong'} key={`${index}-${item.prompt}`}><header><span>{item.correct?'✓':'×'}</span><strong>{index+1}. {item.prompt}</strong></header><dl><div><dt>Réponse de l’apprenant</dt><dd>{item.learnerAnswer}</dd></div><div><dt>Réponse attendue</dt><dd>{item.expectedAnswer}</dd></div></dl><p>{item.explanation}</p></article>)}</div>}{report&&<div className="voice-report result-voice-report"><div><article><h5>Objectifs atteints</h5><ul>{stringList(report.objectivesMet).map((item)=><li key={item}>{item}</li>)}</ul></article><article><h5>Réussites</h5><ul>{stringList(report.successes).map((item)=><li key={item}>{item}</li>)}</ul></article><article><h5>À revoir</h5><ul>{stringList(report.reviewItems).map((item)=><li key={item}>{item}</li>)}</ul></article><article><h5>Vocabulaire maîtrisé</h5><ul>{stringList(report.masteredVocabulary).map((item)=><li key={item}>{item}</li>)}</ul></article><article><h5>Corrections</h5><ul>{stringList(report.corrections).map((item)=><li key={item}>{item}</li>)}</ul></article></div><dl className="voice-report-details"><div><dt>Qualité de l’écoute</dt><dd>{String(report.listeningQuality??'—')}</dd></div><div><dt>Clarté des consignes</dt><dd>{String(report.instructionClarity??'—')}</dd></div><div><dt>Posture professionnelle</dt><dd>{String(report.managementPosture??'—')}</dd></div><div><dt>Meilleure formulation</dt><dd>{String(report.betterResponse??'—')}</dd></div></dl><p><strong>Conseil :</strong> {String(report.tip??'—')}</p><p><strong>Prochain exercice :</strong> {String(report.nextExercise??'—')}</p></div>}</>}<div className="modal-actions"><button className="button dark" type="button" onClick={onClose}>Fermer</button></div></section></div>; }

function ConnectionsView({ notify }: { notify: (message: string) => void }) { const [credential,setCredential] = useState<{ connected: boolean; connectionMode?:'personal'|'platform'|'none'; credential?: { lastFour: string; model: string } | null }>({ connected:false }); const [apiKey,setApiKey] = useState(''); const [model,setModel] = useState('gpt-5.5'); const [resources,setResources] = useState<Array<{ id:string; name:string; url:string; category:string }>>([]); const load = useCallback(() => { api<typeof credential>('/api/credentials').then(setCredential).catch((error) => notify(error.message)); api<{ resources: typeof resources }>('/api/resources').then((data) => setResources(data.resources)).catch((error) => notify(error.message)); },[notify]); useEffect(load,[load]); const connect = async (event: FormEvent) => { event.preventDefault(); try { const data = await api<{ message:string }>('/api/credentials',{ method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({apiKey,model}) }); setApiKey(''); load(); notify(data.message); } catch (error) { notify(error instanceof Error ? error.message : 'Connexion impossible.'); } }; const addResource = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); try { await api('/api/resources',{ method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:data.get('name'),url:data.get('url'),category:data.get('category')}) }); event.currentTarget.reset(); load(); notify('Ressource ajoutée.'); } catch (error) { notify(error instanceof Error ? error.message : 'Ajout impossible.'); } }; const platformManaged=credential.connectionMode==='platform'&&!credential.credential; return <section className="page-view"><div className="page-title"><div><p className="overline">Connexions privées</p><h2>Votre intelligence artificielle et vos ressources.</h2></div></div><div className="settings-grid"><form className="settings-card" onSubmit={connect}><div className="settings-icon">✧</div><h3>{platformManaged?'Connexion IA sécurisée':'Votre connexion OpenAI personnelle'}</h3><p>{platformManaged?'La connexion principale est gérée exclusivement côté serveur. Sa clé n’est jamais transmise au navigateur ni affichée aux utilisateurs.':'Votre clé facultative est testée puis chiffrée côté serveur. L’administrateur ne peut jamais la consulter.'}</p>{credential.connected && <div className="success-banner">✓ {platformManaged?'Connexion serveur active':`Connexion personnelle validée · clé •••• ${credential.credential?.lastFour??''}`}</div>}{!platformManaged&&<><label>Clé API OpenAI<input type="password" autoComplete="off" value={apiKey} onChange={(event) => setApiKey(event.target.value)} placeholder="sk-…" required /></label><label>Modèle<select value={model} onChange={(event)=>setModel(event.target.value)}><option value="gpt-5.4-mini">gpt-5.4-mini</option><option value="gpt-5.5">gpt-5.5</option><option value="gpt-5.6-luna">gpt-5.6-luna</option><option value="gpt-5.6-terra">gpt-5.6-terra</option><option value="gpt-5.6-sol">gpt-5.6-sol</option></select></label><button className="button dark" type="submit">{credential.credential ? 'Remplacer ma clé' : 'Connecter ma clé personnelle'}</button>{credential.credential && <button className="button light danger-text" type="button" onClick={async () => { if (!window.confirm('Voulez-vous supprimer votre clé OpenAI chiffrée ?')) return; await api('/api/credentials',{method:'DELETE'}); load(); notify('Clé supprimée.'); }}>Supprimer ma clé</button>}</>}</form><form className="settings-card" onSubmit={addResource}><div className="settings-icon">↗</div><h3>Ajouter une ressource externe</h3><p>Canva, Genially, YouTube, Google Forms, LearningApps ou autre adresse HTTPS.</p><label>Nom<input name="name" required placeholder="Ex. Vidéo sur le bionettoyage" /></label><label>Adresse HTTPS<input name="url" type="url" required placeholder="https://…" /></label><label>Catégorie<select name="category"><option>Canva</option><option>Genially</option><option>YouTube</option><option>Google Forms</option><option>LearningApps</option><option>Autre</option></select></label><button className="button dark" type="submit">Ajouter la ressource</button></form></div><div className="resource-list">{resources.map((resource) => <article key={resource.id}><span>{resource.category}</span><strong>{resource.name}</strong><a href={resource.url} target="_blank" rel="noreferrer">Ouvrir ↗</a><button type="button" onClick={async () => { if (!window.confirm('Voulez-vous vraiment supprimer cette ressource ?')) return; await api(`/api/resources?id=${resource.id}`,{method:'DELETE'}); load(); }}>Supprimer</button></article>)}</div></section>; }

export const legacyConnectionsView = ConnectionsView;

function AdminView({ notify }: { notify: (message: string) => void }) {
  const [requests,setRequests] = useState<TrainerAccessRow[]>([]);
  const [billing,setBilling] = useState<AdminBillingData|null>(null);
  const [busyId,setBusyId] = useState('');
  const [issuedCodes,setIssuedCodes] = useState<Record<string,{code:string;expiresAt:number}>>({});
  const load = useCallback(() => Promise.all([api<{ requests: TrainerAccessRow[] }>('/api/admin/requests'),api<AdminBillingData>('/api/admin/billing')]).then(([access,billingData])=>{setRequests(access.requests);setBilling(billingData);}).catch((error) => notify(error.message)),[notify]);
  useEffect(() => { void load(); const timer=window.setInterval(()=>void load(),30_000);return()=>window.clearInterval(timer); },[load]);

  const action = async (trainerId: string, name: string, values: Record<string,unknown> = {}) => {
    setBusyId(trainerId);
    try {
      const data = await api<{ message:string; mailto?:string; code?:string; expiresAt?:number }>('/api/admin/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({trainerId,action:name,...values})});
      if (data.code && data.expiresAt) setIssuedCodes((current) => ({ ...current,[trainerId]:{ code:data.code!,expiresAt:data.expiresAt! } }));
      if (data.mailto) window.location.href = data.mailto;
      notify(data.message);
      await load();
    } catch (error) {
      notify(error instanceof Error ? error.message : 'Action impossible.');
    } finally { setBusyId(''); }
  };

  const savePermissions = async (trainerId: string, permissions: TrainerPermissions) => {
    setBusyId(trainerId);
    try {
      const data = await api<{ message:string }>('/api/admin/requests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({trainerId,action:'update_permissions',permissions})});
      notify(data.message);
      await load();
    } catch (error) {
      notify(error instanceof Error ? error.message : 'Enregistrement des droits impossible.');
    } finally { setBusyId(''); }
  };

  const billingAction=async(body:Record<string,unknown>)=>{setBusyId(String(body.userId??body.planId??'billing'));try{const data=await api<{message:string}>('/api/admin/billing',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});notify(data.message);await load();}catch(error){notify(error instanceof Error?error.message:'Mise à jour impossible.');}finally{setBusyId('');}};

  return <section className="page-view">
    <div className="page-title"><div><p className="overline">Espace administrateur</p><h2>Utilisateurs, formules et maîtrise des coûts.</h2></div><button className="button light" type="button" onClick={()=>void load()}>↻ Actualiser les compteurs</button></div>
    <div className="admin-notice"><strong>Les droits, quotas et crédits sont contrôlés côté serveur.</strong><span>Une formule donne les accès généraux ; vous pouvez ensuite ajouter une exception individuelle, temporaire ou permanente.</span></div>
    <AdminSupportCenter notify={notify}/>
    {billing&&<SubscriptionAdministration data={billing} busyId={busyId} onAction={billingAction}/>}
    <div className="admin-section-heading"><p className="overline">Validation des comptes</p><h3>Inscriptions et droits opérationnels</h3></div>
    {requests.some((request)=>request.accountStatus==='pending') && <div className="pending-access-alert"><strong>{requests.filter((request)=>request.accountStatus==='pending').length} demande(s) à traiter</strong><span>Choisissez d’abord la formule et les droits, puis créez le code à remettre au formateur.</span></div>}
    <div className="request-list trainer-request-list">
      {requests.map((request) => <TrainerPermissionCard key={`${request.id}-${Object.values(request.permissions).map(Number).join('')}`} request={request} issuedCode={issuedCodes[request.trainerId]} busy={busyId === request.trainerId} onSave={savePermissions} onAction={action} />)}
      {!requests.length && <EmptyState title="Aucune inscription à gérer" copy="Les nouvelles demandes d’accès apparaîtront automatiquement ici avec le nom, le prénom et l’adresse e-mail du formateur." />}
    </div>
  </section>;
}

function SubscriptionAdministration({data,busyId,onAction}:{data:AdminBillingData;busyId:string;onAction:(body:Record<string,unknown>)=>Promise<void>}){return <div className="subscription-admin"><section className="admin-kpis"><article><span>Utilisateurs</span><strong>{data.totals.users}</strong><small>{data.totals.active} actif(s)</small></article><article><span>Temps vocal consommé</span><strong>{formatVoiceDuration(data.totals.voiceSeconds)}</strong><small>ce mois</small></article><article><span>Coût API estimé</span><strong>{formatEuros(data.totals.apiCostMicros/1_000_000)}</strong><small>ce mois</small></article><article className={data.totals.nearLimit?'warning':''}><span>Proches d’une limite</span><strong>{data.totals.nearLimit}</strong><small>quota vocal ou budget</small></article></section><AiSecurityEditor settings={data.aiSecurity} busy={busyId==='billing'} onSave={(values)=>onAction({action:'update_ai_security',...values})}/><PlanStatistics data={data}/><AdminConsumptionAlerts members={data.members}/><details className="plan-management"><summary><span><b>Gestion des formules</b><small>Prix, quotas, crédits, budget et fonctionnalités restent modifiables.</small></span><i>Ouvrir les réglages</i></summary><div className="plan-editor-grid">{data.plans.map((plan)=><PlanEditor key={`${plan.id}-${plan.updatedAt}`} plan={plan} busy={busyId===plan.id} onSave={(values)=>onAction({action:'update_plan_config',planId:plan.id,...values})}/>)}</div></details><section className="member-management"><div className="admin-section-heading"><p className="overline">Fiches utilisateurs</p><h3>Abonnements, quotas et exceptions</h3></div><div className="member-billing-list">{data.members.map((member)=><MemberBillingCard key={`${member.id}-${member.entitlement.updatedAt}`} member={member} plans={data.plans} busy={busyId===member.id} onAction={onAction}/>)}</div></section></div>}

function AiSecurityEditor({settings,busy,onSave}:{settings:AdminBillingData['aiSecurity'];busy:boolean;onSave:(values:Record<string,unknown>)=>Promise<void>}){const[state,setState]=useState(settings);const change=(key:keyof typeof settings,value:string)=>setState((current)=>({...current,[key]:Math.max(1,Number(value)||1)}));return <details className="plan-management ai-security-management"><summary><span><b>Protections globales de l’intelligence artificielle</b><small>Limites serveur indépendantes des boutons affichés dans l’interface.</small></span><i>Ouvrir les garde-fous</i></summary><div className="ai-security-grid"><label>Requêtes / minute / utilisateur<input type="number" min="1" max="120" value={state.requestsPerMinute} onChange={(event)=>change('requestsPerMinute',event.target.value)}/></label><label>Requêtes / jour / utilisateur<input type="number" min="1" value={state.requestsPerDay} onChange={(event)=>change('requestsPerDay',event.target.value)}/></label><label>Plafond global / jour<input type="number" min="1" value={state.globalRequestsPerDay} onChange={(event)=>change('globalRequestsPerDay',event.target.value)}/></label><label>Budget global quotidien (€)<input type="number" min="1" step="0.10" value={(state.globalDailyBudgetMicros/1_000_000).toFixed(2)} onChange={(event)=>change('globalDailyBudgetMicros',String(Math.round(Number(event.target.value)*1_000_000)))}/></label><label>Taille JSON maximale (Ko)<input type="number" min="10" value={Math.round(state.maxJsonBytes/1000)} onChange={(event)=>change('maxJsonBytes',String(Number(event.target.value)*1000))}/></label><button className="button dark" disabled={busy} type="button" onClick={()=>void onSave(state)}>{busy?'Enregistrement…':'Enregistrer les protections'}</button></div></details>}

function PlanEditor({plan,busy,onSave}:{plan:BillingPlan;busy:boolean;onSave:(values:Record<string,unknown>)=>Promise<void>}){const[state,setState]=useState(plan);const number=(field:keyof BillingPlan,value:string)=>setState((current)=>({...current,[field]:Math.max(0,Number(value)||0)}));return <article className="plan-editor"><header><div><strong>{state.name}</strong><small>{dataPlanCountLabel(state.id)}</small></div><label className="switch-row"><input type="checkbox" checked={state.active} onChange={(event)=>setState((current)=>({...current,active:event.target.checked}))}/> Active</label></header><div className="form-row two"><label>Nom<input value={state.name} onChange={(event)=>setState((current)=>({...current,name:event.target.value}))}/></label><label>Prix mensuel (€)<input type="number" min="0" step="0.10" value={(state.priceCents/100).toFixed(2)} onChange={(event)=>number('priceCents',String(Math.round(Number(event.target.value)*100)))}/></label></div><div className="form-row two"><label>Vocal mensuel (min)<input type="number" min="0" value={Math.round(state.monthlyVoiceSeconds/60)} onChange={(event)=>number('monthlyVoiceSeconds',String(Number(event.target.value)*60))}/></label><label>Vocal quotidien (min)<input type="number" min="0" value={Math.round(state.dailyVoiceSeconds/60)} onChange={(event)=>number('dailyVoiceSeconds',String(Number(event.target.value)*60))}/></label></div><div className="form-row two"><label>Crédits mensuels<input type="number" min="0" value={state.monthlyCredits} onChange={(event)=>number('monthlyCredits',event.target.value)}/></label><label>Budget API interne (€)<input type="number" min="0" step="0.10" value={(state.monthlyApiBudgetMicros/1_000_000).toFixed(2)} onChange={(event)=>number('monthlyApiBudgetMicros',String(Math.round(Number(event.target.value)*1_000_000)))}/></label></div><fieldset className="plan-feature-grid"><legend>Fonctionnalités incluses</legend>{SUBSCRIPTION_FEATURES.map((feature)=><label key={feature} className={state.features[feature]?'enabled':''}><input type="checkbox" checked={state.features[feature]} onChange={(event)=>setState((current)=>({...current,features:{...current.features,[feature]:event.target.checked}}))}/>{FEATURE_LABELS[feature]}</label>)}</fieldset><button className="button dark" type="button" disabled={busy} onClick={()=>void onSave({name:state.name,priceCents:state.priceCents,monthlyVoiceSeconds:state.monthlyVoiceSeconds,dailyVoiceSeconds:state.dailyVoiceSeconds,monthlyCredits:state.monthlyCredits,monthlyApiBudgetMicros:state.monthlyApiBudgetMicros,features:state.features,creditCosts:state.creditCosts,active:state.active})}>{busy?'Enregistrement…':'Enregistrer la formule'}</button></article>}

function MemberBillingCard({member,plans,busy,onAction}:{member:BillingMember;plans:BillingPlan[];busy:boolean;onAction:(body:Record<string,unknown>)=>Promise<void>}){const[planId,setPlanId]=useState(member.entitlement.planId);const[status,setStatus]=useState(member.entitlement.subscriptionStatus);const[startsAt,setStartsAt]=useState(toDateInput(member.entitlement.startsAt));const[renewsAt,setRenewsAt]=useState(toDateInput(member.entitlement.renewsAt));const[endsAt,setEndsAt]=useState(toDateInput(member.entitlement.endsAt));const[creditDelta,setCreditDelta]=useState('');const[limits,setLimits]=useState({monthly:member.entitlement.unlimited?'':String(Math.round(member.entitlement.monthlyVoiceLimit/60)),daily:member.entitlement.unlimited?'':String(Math.round(member.entitlement.dailyVoiceLimit/60)),credits:'',budget:String((member.entitlement.apiBudgetMicros/1_000_000).toFixed(2)),unlimited:member.entitlement.unlimited});const fullName=[member.firstName,member.lastName].filter(Boolean).join(' ')||member.displayName||member.email;const overrideValue=(feature:SubscriptionFeature)=>{const override=member.entitlement.overrides.find((item)=>item.feature===feature);return override?String(override.allowed):'default';};return <details className="member-billing-card"><summary><span className="avatar">{initials(fullName)}</span><span><strong>{fullName}</strong><small>{member.email} · {member.entitlement.planName}</small></span><div className="member-summary-metrics"><b>{member.entitlement.unlimited?'Vocal illimité':`${formatVoiceDuration(member.entitlement.voiceSecondsMonth)} / ${formatVoiceDuration(member.entitlement.monthlyVoiceLimit)}`}</b><b>{member.entitlement.unlimited?'Crédits illimités':`${member.entitlement.creditsRemaining} crédits`}</b></div></summary><div className="member-billing-body"><section><h4>Abonnement</h4><div className="form-row two"><label>Formule<select value={planId} onChange={(event)=>setPlanId(event.target.value)}>{plans.filter((plan)=>plan.active||plan.id===planId).map((plan)=><option key={plan.id} value={plan.id}>{plan.name}</option>)}</select></label><label>Statut<select value={status} onChange={(event)=>setStatus(event.target.value)}><option value="active">Actif</option><option value="trial">Essai</option><option value="free">Gratuit / test</option><option value="suspended">Suspendu</option><option value="expired">Expiré</option><option value="canceled">Résilié</option></select></label></div><div className="form-row three"><label>Début<input type="date" value={startsAt} onChange={(event)=>setStartsAt(event.target.value)}/></label><label>Renouvellement<input type="date" value={renewsAt} onChange={(event)=>setRenewsAt(event.target.value)}/></label><label>Fin éventuelle<input type="date" value={endsAt} onChange={(event)=>setEndsAt(event.target.value)}/></label></div><button className="button dark" disabled={busy} type="button" onClick={()=>void onAction({action:'change_plan',userId:member.id,planId,status,startsAt:dateToSeconds(startsAt),renewsAt:dateToSeconds(renewsAt),endsAt:dateToSeconds(endsAt)})}>Modifier la formule</button></section><section><h4>Consommation et crédits</h4><div className="quota-meter"><span>Vocal mensuel</span><b>{member.entitlement.unlimited?'Illimité':`${formatVoiceDuration(member.entitlement.voiceSecondsMonth)} / ${formatVoiceDuration(member.entitlement.monthlyVoiceLimit)}`}</b><i><em style={{width:`${member.entitlement.voiceSecondsMonth>0?Math.max(1,member.entitlement.voicePercent):0}%`}}/></i></div><div className="quota-meter"><span>Budget API interne</span><b>{member.entitlement.unlimited?'Suivi sans plafond':`${formatEuros(member.entitlement.apiCostMicrosMonth/1_000_000)} / ${formatEuros(member.entitlement.apiBudgetMicros/1_000_000)}`}</b><i><em style={{width:`${member.entitlement.apiPercent}%`}}/></i></div><div className="credit-adjust"><input type="number" value={creditDelta} onChange={(event)=>setCreditDelta(event.target.value)} placeholder="+100 ou -20"/><button className="button light" disabled={busy||!Number(creditDelta)} type="button" onClick={()=>{void onAction({action:'adjust_credits',userId:member.id,amount:Number(creditDelta)});setCreditDelta('');}}>Ajuster les crédits</button></div></section><section><h4>Quotas personnalisés</h4><label className="switch-row"><input type="checkbox" checked={limits.unlimited} onChange={(event)=>setLimits((current)=>({...current,unlimited:event.target.checked}))}/> Accès illimité pour ce compte</label><div className="form-row two"><label>Vocal mensuel (min)<input type="number" min="0" disabled={limits.unlimited} value={limits.monthly} onChange={(event)=>setLimits((current)=>({...current,monthly:event.target.value}))}/></label><label>Vocal quotidien (min)<input type="number" min="0" disabled={limits.unlimited} value={limits.daily} onChange={(event)=>setLimits((current)=>({...current,daily:event.target.value}))}/></label><label>Crédits mensuels (optionnel)<input type="number" min="0" value={limits.credits} onChange={(event)=>setLimits((current)=>({...current,credits:event.target.value}))} placeholder="Selon la formule"/></label><label>Budget API (€)<input type="number" min="0" step="0.10" disabled={limits.unlimited} value={limits.budget} onChange={(event)=>setLimits((current)=>({...current,budget:event.target.value}))}/></label></div><button className="button light" disabled={busy} type="button" onClick={()=>void onAction({action:'update_limits',userId:member.id,unlimited:limits.unlimited,voiceMonthlyOverrideSeconds:limits.monthly?Number(limits.monthly)*60:null,voiceDailyOverrideSeconds:limits.daily?Number(limits.daily)*60:null,creditsMonthlyOverride:limits.credits?Number(limits.credits):null,apiBudgetOverrideMicros:limits.budget?Math.round(Number(limits.budget)*1_000_000):null})}>Enregistrer les quotas</button></section><section><h4>Exceptions individuelles</h4><div className="feature-override-grid">{SUBSCRIPTION_FEATURES.map((feature)=><label key={feature}><span>{FEATURE_LABELS[feature]}<small>{member.entitlement.features[feature]?'Accès actif':'Accès bloqué'}</small></span><select value={overrideValue(feature)} onChange={(event)=>void onAction({action:'update_override',userId:member.id,feature,allowed:event.target.value==='default'?null:event.target.value==='true'})}><option value="default">Selon formule</option><option value="true">Oui</option><option value="false">Non</option></select></label>)}</div></section>{member.history.length>0&&<section><h4>Historique récent</h4><ol className="subscription-history">{member.history.slice(0,6).map((event)=><li key={event.id}><span>{subscriptionActionLabel(event.action,event.fromPlanId,event.toPlanId)}</span><time>{new Date(event.createdAt*1000).toLocaleString('fr-FR')}</time></li>)}</ol></section>}</div></details>}

function toDateInput(value:number|null){return value?new Date(value*1000).toISOString().slice(0,10):''}function dateToSeconds(value:string){return value?Math.floor(new Date(`${value}T12:00:00Z`).getTime()/1000):null}function formatEuros(value:number){return new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(value)}function formatVoiceDuration(seconds:number){const safe=Math.max(0,Math.round(seconds));const minutes=Math.floor(safe/60);const remaining=safe%60;if(minutes&&remaining)return `${minutes} min ${remaining} s`;if(minutes)return `${minutes} min`;return `${remaining} s`;}function dataPlanCountLabel(id:string){return id==='essential'?'Offre pédagogique de base':id==='coach'?'Vocal et accompagnement':'Accès intensif et avancé'}function subscriptionActionLabel(action:string,from:string|null,to:string|null){if(action==='plan_changed')return `Formule modifiée : ${from??'—'} → ${to??'—'}`;if(action==='credits_adjusted')return 'Crédits ajustés par l’administrateur';if(action==='feature_override')return 'Droit individuel modifié';if(action==='limits_updated')return 'Quotas personnalisés modifiés';return action}

function TrainerPermissionCard({ request,issuedCode,busy,onSave,onAction }: { request: TrainerAccessRow; issuedCode?: {code:string;expiresAt:number}; busy: boolean; onSave: (trainerId: string, permissions: TrainerPermissions) => Promise<void>; onAction: (trainerId: string, action: string, values?:Record<string,unknown>) => Promise<void> }) {
  const [permissions,setPermissions] = useState<TrainerPermissions>(request.permissions);
  const [note,setNote] = useState(request.note ?? '');
  const level = detectPermissionLevel(permissions);
  const fullName = [request.firstName,request.lastName].filter(Boolean).join(' ') || request.displayName || request.email;
  const applyPreset = (preset: Exclude<PermissionLevel,'custom'>) => setPermissions({ ...PERMISSION_PRESETS[preset] });

  return <article className="trainer-card">
    <div className="trainer-card-header">
      <div><span className={`status-pill ${request.accountStatus}`}>{accountStatusLabel(request.accountStatus)}</span><h3>{fullName}</h3><a href={`mailto:${request.email}`}>{request.email}</a><small>Inscription du {new Date(request.requestedAt * 1000).toLocaleDateString('fr-FR')} · Formule : {request.planName ?? 'à définir'}</small></div>
      <div className="trainer-account-actions">
        {request.accountStatus === 'pending' && <><button className="button dark" disabled={busy} type="button" onClick={() => onAction(request.trainerId,'approve')}>{request.codeHint ? 'Créer un nouveau code' : 'Autoriser et créer le code'}</button><button className="button light danger-text" disabled={busy} type="button" onClick={() => onAction(request.trainerId,'refuse')}>Refuser</button></>}
        {request.accountStatus === 'active' && <button className="button light" disabled={busy} type="button" onClick={() => onAction(request.trainerId,'suspend')}>Suspendre</button>}
        {(request.accountStatus === 'suspended' || request.accountStatus === 'revoked') && <button className="button dark" disabled={busy} type="button" onClick={() => onAction(request.trainerId,'reactivate')}>Réactiver</button>}
        {request.accountStatus !== 'revoked' && request.accountStatus !== 'pending' && <button className="button light danger-text" disabled={busy} type="button" onClick={() => onAction(request.trainerId,'revoke')}>Révoquer</button>}
      </div>
    </div>
    <section className="trainer-support-panel">
      <div><strong>Code d’accès et assistance</strong><span>{issuedCode ? `Code à remettre : ${issuedCode.code}` : request.codeHint ? `Code remis : ${request.codeHint}` : 'Aucun code créé'}</span><small>{issuedCode ? `Visible une seule fois · expire le ${new Date(issuedCode.expiresAt*1000).toLocaleDateString('fr-FR')}` : request.codeUsedAt ? `Code utilisé le ${new Date(request.codeUsedAt*1000).toLocaleDateString('fr-FR')}` : request.codeExpiresAt ? `Expiration : ${new Date(request.codeExpiresAt*1000).toLocaleDateString('fr-FR')}` : 'Le compte reste en attente tant que le code n’est pas utilisé.'}</small></div>
      {issuedCode && <button className="button light" type="button" onClick={() => { void navigator.clipboard.writeText(issuedCode.code); }}>Copier le code</button>}
      <label>Note de suivi<input value={note} onChange={(event)=>setNote(event.target.value)} placeholder="Ex. Difficulté de connexion, navigateur, demande particulière…" /></label>
      <button className="button light" disabled={busy} type="button" onClick={() => onAction(request.trainerId,'update_note',{note})}>Enregistrer la note</button>
    </section>
    <div className="permission-editor">
      <div className="permission-heading"><div><strong>Niveau d’accès</strong><span>Profil actuel : {permissionLevelLabel(level)}</span></div><div className="access-profile-tabs" aria-label="Choisir un niveau de droits">{(['limited','medium','extended'] as const).map((preset) => <button className={level === preset ? 'active' : ''} type="button" key={preset} onClick={() => applyPreset(preset)}>{permissionLevelLabel(preset)}</button>)}</div></div>
      <div className="permission-grid">{PERMISSION_DEFINITIONS.map((definition) => <label className={`permission-option ${permissions[definition.key] ? 'enabled' : ''}`} key={definition.key}><input type="checkbox" checked={permissions[definition.key]} onChange={(event) => setPermissions((current) => ({ ...current,[definition.key]:event.target.checked }))} /><span><strong>{definition.label}</strong><small>{definition.description}</small></span></label>)}</div>
      <div className="permission-save"><span>{level === 'custom' ? 'Réglage personnalisé' : `Profil ${permissionLevelLabel(level).toLowerCase()}`} · {Object.values(permissions).filter(Boolean).length} droit(s) accordé(s)</span><button className="button dark" disabled={busy} type="button" onClick={() => onSave(request.trainerId,permissions)}>{busy ? 'Enregistrement…' : 'Enregistrer les droits'}</button></div>
    </div>
  </article>;
}

function AuthDialog({ resetToken,initialMode,initialAccess,platformUser,adminInitialized,onClose,onAuthenticated }: { resetToken: string; initialMode: 'login'|'register'; initialAccess:'learner'|null; platformUser: PlatformUser | null; adminInitialized: boolean; onClose: () => void; onAuthenticated: (user: User) => void }) {
  const [mode,setMode] = useState<'login'|'register'|'activate'|'forgot'>(resetToken ? 'forgot' : initialMode);
  const [message,setMessage] = useState(''); const [busy,setBusy] = useState(false);
  const selectMode = (next: 'login'|'register'|'activate'|'forgot') => { setMode(next); setMessage(''); };
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setBusy(true); setMessage(''); const data = Object.fromEntries(new FormData(event.currentTarget));
    try {
      if (mode === 'login') { const result = await api<{ user: User }>('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}); onAuthenticated(result.user); }
      else if (mode === 'register') { const result = await api<{ status:string; message:string }>('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}); setMessage(result.message); if (result.status === 'active') { const me = await api<{ user: User }>('/api/auth/me'); onAuthenticated(me.user); } else setMode('activate'); }
      else if (mode === 'activate') { const result = await api<{ message:string }>('/api/auth/activate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}); setMessage(result.message); const me = await api<{ user: User }>('/api/auth/me'); onAuthenticated(me.user); }
      else if (resetToken) { const result = await api<{ message:string }>('/api/auth/password-reset/confirm',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,token:resetToken})}); window.history.replaceState({},'',window.location.pathname); setMessage(result.message); setMode('login'); }
      else { const result = await api<{ message:string }>('/api/auth/password-reset/request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}); setMessage(result.message); }
    } catch (error) { setMessage(error instanceof Error ? error.message : 'Action impossible.'); } finally { setBusy(false); }
  };
  const title = mode === 'login' ? initialAccess==='learner'?'Connexion à l’espace apprenant.':'Se connecter.' : mode === 'register' ? 'Créer mon compte.' : mode === 'activate' ? 'Activer mon compte.' : resetToken ? 'Choisir un nouveau mot de passe.' : 'Retrouver mon accès.';
  return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="auth-title"><form className="modal-card auth-card" onSubmit={submit}><button className="modal-close" type="button" onClick={onClose} aria-label="Fermer">×</button><BrandMark priority/><p className="overline">Espace sécurisé</p><h2 id="auth-title">{title}</h2>{mode==='login'&&initialAccess==='learner'&&<div className="identity-note"><strong>Votre lien de retour permanent</strong><span>Connectez-vous avec votre adresse e-mail et votre mot de passe. Une fois dans votre espace, vous pourrez installer l’application sur cet appareil.</span></div>}{mode === 'register' && <div className="identity-note"><strong>{adminInitialized ? 'Inscription formateur' : platformUser ? '✓ Identité sécurisée reconnue' : 'Inscription sécurisée'}</strong><span>{adminInitialized ? 'Renseignez votre identité, votre adresse e-mail et un mot de passe. L’administrateur verra votre demande, choisira votre formule et vous remettra un code d’accès.' : 'Saisissez simplement votre adresse et choisissez un mot de passe. Le compte administrateur sera ouvert immédiatement.'}</span></div>}{mode === 'activate' && <div className="identity-note"><strong>Code remis par l’administrateur</strong><span>Saisissez le code reçu. Votre mot de passe ne change pas et servira ensuite pour vos connexions.</span></div>}{mode !== 'forgot' && <div className="tab-list three-tabs" role="tablist"><button type="button" role="tab" aria-selected={mode==='login'} className={mode === 'login' ? 'active':''} onClick={() => selectMode('login')}>Connexion</button><button type="button" role="tab" aria-selected={mode==='register'} className={mode === 'register' ? 'active':''} onClick={() => selectMode('register')}>Créer un compte</button><button type="button" role="tab" aria-selected={mode==='activate'} className={mode === 'activate' ? 'active':''} onClick={() => selectMode('activate')}>J’ai mon code</button></div>}{mode === 'register' && platformUser && <input name="displayName" type="hidden" value={platformUser.displayName} />}{mode === 'register' && adminInitialized && <div className="form-row two"><label>Prénom<input name="firstName" autoComplete="given-name" required /></label><label>Nom<input name="lastName" autoComplete="family-name" required /></label></div>}{(!resetToken || mode !== 'forgot') && <label>Adresse e-mail<input name="email" type="email" autoComplete="email" defaultValue={platformUser?.email ?? ''} required /></label>}{mode === 'login' && <label>Mot de passe<input name="password" type="password" autoComplete="current-password" required /></label>}{mode === 'register' && <><label>Créer un mot de passe<input name="password" type="password" autoComplete="new-password" required /></label><small>Au moins 12 caractères, dont une majuscule, une minuscule, un chiffre et un caractère spécial.</small></>}{mode === 'activate' && <label>Code d’accès<input name="code" autoComplete="one-time-code" placeholder="PP-XXXX-XXXX" required /></label>}{mode === 'forgot' && resetToken && <><label>Nouveau mot de passe<input name="password" type="password" autoComplete="new-password" required /></label><label>Confirmer le mot de passe<input name="passwordConfirmation" type="password" autoComplete="new-password" required /></label><small>12 caractères minimum avec majuscule, minuscule, chiffre et caractère spécial.</small></>}{message && <p className="form-message" role="status">{message}</p>}<button className="button dark full" type="submit" disabled={busy}>{busy ? 'Traitement sécurisé…' : mode === 'login' ? 'Se connecter' : mode === 'register' ? 'Créer mon compte' : mode === 'activate' ? 'Activer mon accès' : resetToken ? 'Remplacer mon mot de passe' : 'Envoyer le lien sécurisé'}</button>{mode === 'login' && <button className="link-button" type="button" onClick={() => selectMode('forgot')}>Mot de passe oublié ?</button>}{mode === 'forgot' && !resetToken && <button className="link-button" type="button" onClick={() => selectMode('login')}>Revenir à la connexion</button>}</form></div>;
}

function PlanStatistics({data}:{data:AdminBillingData}) {
  const [simulatedPlanId,setSimulatedPlanId]=useState(data.plans[0]?.id??'essential');
  const simulatedPlan=data.plans.find((plan)=>plan.id===simulatedPlanId)??data.plans[0];
  return <section className="plan-statistics"><div className="admin-section-heading"><p className="overline">Pilotage des offres</p><h3>Statistiques et aperçu par formule</h3></div><div className="plan-stat-grid">{data.plans.map((plan)=>{const members=data.members.filter((member)=>member.entitlement.planId===plan.id);const averageVoice=members.length?Math.round(members.reduce((sum,member)=>sum+member.entitlement.voiceSecondsMonth,0)/members.length/60):0;const averageCost=members.length?members.reduce((sum,member)=>sum+member.entitlement.apiCostMicrosMonth,0)/members.length/1_000_000:0;return <article key={plan.id}><strong>{plan.name}</strong><span>{members.length} abonné(s)</span><small>Vocal moyen : {averageVoice} min</small><small>Coût API moyen : {formatEuros(averageCost)}</small></article>})}</div>{simulatedPlan&&<div className="plan-simulation"><label>Prévisualiser les droits d’une formule<select value={simulatedPlanId} onChange={(event)=>setSimulatedPlanId(event.target.value)}>{data.plans.map((plan)=><option key={plan.id} value={plan.id}>{plan.name}</option>)}</select></label><div>{SUBSCRIPTION_FEATURES.map((feature)=><span key={feature} className={simulatedPlan.features[feature]?'enabled':'disabled'}>{simulatedPlan.features[feature]?'✓':'×'} {FEATURE_LABELS[feature]}</span>)}</div></div>}</section>;
}

function AdminConsumptionAlerts({members}:{members:BillingMember[]}) {
  const alerts=members.filter((member)=>!member.entitlement.unlimited&&(member.entitlement.voicePercent>=75||member.entitlement.apiPercent>=75));
  if(!alerts.length)return <section className="admin-consumption-alerts clear"><strong>✓ Consommation sous contrôle</strong><span>Aucun compte n’approche actuellement de son quota vocal ou de son budget API.</span></section>;
  return <section className="admin-consumption-alerts"><strong>Alertes de consommation</strong>{alerts.map((member)=>{const name=[member.firstName,member.lastName].filter(Boolean).join(' ')||member.displayName||member.email;return <span key={member.id}>{name} : vocal {member.entitlement.voicePercent}% · budget API {member.entitlement.apiPercent}%.</span>})}</section>;
}

function EmptyState({ title,copy,action }: { title:string; copy:string; action?: () => void }) { return <div className="empty-state"><span>✦</span><h3>{title}</h3><p>{copy}</p>{action && <button className="button dark" type="button" onClick={action}>Commencer</button>}</div>; }
function initials(value:string) { return value.split(/\s|@/).filter(Boolean).slice(0,2).map((part) => part[0]).join('').toUpperCase(); }
function firstName(value:string) { return value.split(/[\s@]/)[0] || 'formateur'; }
function accountStatusLabel(status:string) { return ({ pending:'En attente',active:'Actif',suspended:'Suspendu',revoked:'Révoqué' } as Record<string,string>)[status] ?? status; }
function permissionLevelLabel(level: PermissionLevel) { return ({ limited:'Limité',medium:'Moyen',extended:'Étendu',custom:'Personnalisé' } as Record<PermissionLevel,string>)[level]; }
